#define _COMPILE_B_
#include <stdlib.h>
#include <stdio.h>
#include <string.h>

const char *get_self();

#ifdef _COMPILE_A_
#include <stdlib.h>
#include <stdio.h>

int main(int argc, char **argv) {
  if (argc != 2) {
    printf("This is app Alfa.\n");
  } else {
    int app = atoi(argv[1]);
    const char *S = get_self();
    printf("#define _COMPILE_%c_\n%s", (app == 1) ? 'A' : 'B', S);
  }
  return 0;
}
#endif
#ifdef _COMPILE_B_
#include <stdlib.h>
#include <stdio.h>

int main(int argc, char **argv) {
  if (argc != 2) {
    printf("This is app Bravo.\n");
  } else {
    int app = atoi(argv[1]);
    const char *S = get_self();
    printf("#define _COMPILE_%c_\n%s", (app == 1) ? 'B' : 'A', S);
  }
  return 0;
}
#endif

const char*prologue="";
const char*selfref="";

size_t hex2bin(const char*hex,char**bin) {
  char*dst=*bin=malloc(strlen(hex)/2+1);
  while(*hex){sscanf(hex,"%2hhx",dst++),hex+=2;}
  return *dst=0,(dst-*bin);
}

const char*get_self() {
  static char*self;
  if (!self) {
    char*decP,*decSR;
    size_t cP=hex2bin(prologue,&decP),cSR=hex2bin(selfref,&decSR);
    self=malloc(cP+cSR+strlen(prologue)+strlen(selfref)+1000);
    sprintf(self,"%sconst char*prologue=%c%s%c;\nconst char*selfref=%c%s%c;\n\n%s",decP,34,prologue,34,34,selfref,34,decSR);
    free(decP),free(decSR);
  }
  return self;
}
